package chatui

const ChatFilterStyles = `.chatfilter-panel{box-sizing:border-box;min-width:0;max-width:100%;padding:16px;border:1px solid var(--hcm-color-border);border-radius:var(--hcm-radius-control);color:var(--hcm-color-text);background:var(--hcm-color-surface)}.chatfilter-panel *{box-sizing:border-box;min-width:0}.chatfilter-form{display:grid;gap:8px}.chatfilter-panel input,.chatfilter-panel select,.chatfilter-panel textarea,.chatfilter-panel button{min-height:44px;max-width:100%;border:1px solid var(--hcm-color-border);border-radius:var(--hcm-radius-control);color:inherit;background:var(--hcm-color-surface)}.chatfilter-panel input,.chatfilter-panel select,.chatfilter-panel textarea{width:100%;padding:8px}.chatfilter-panel button{padding:8px 12px;white-space:normal}.chatfilter-panel .chatfilter-primary{background:var(--hcm-color-brand-primary);color:var(--hcm-color-on-brand)}.chatfilter-panel :focus-visible{outline:2px solid var(--hcm-color-brand-primary);outline-offset:2px}.chatfilter-list{list-style:none;padding:0;display:grid;gap:12px}.chatfilter-rule{overflow-wrap:anywhere;display:flex;flex-wrap:wrap;gap:8px;align-items:center}.chatfilter-rule-name{flex:1 1 160px}.chatfilter-blocked{white-space:pre-wrap;overflow-wrap:anywhere}.chatfilter-blocked mark{color:inherit;background:var(--hcm-color-surface);text-decoration:underline wavy var(--hcm-color-danger);text-underline-offset:4px}.chatfilter-removed{font-style:italic;overflow-wrap:anywhere}.chatfilter-check{display:flex;align-items:center;gap:8px}.chatfilter-check input{width:24px;flex:none}@media(max-width:390px){.chatfilter-panel{padding:8px}.chatfilter-rule{display:grid;grid-template-columns:minmax(0,1fr)}}@media(prefers-reduced-motion:reduce){.chatfilter-panel *{transition:none;animation:none}}` + ChatMod003Styles
